def histogram(values: list[float], bins: int, lo: float, hi: float) -> list[int]:
    """Counts of values per equal-width bin over [lo, hi); values outside the range are ignored."""
    counts: list[int] = []
    for b in range(bins):
        counts.append(0)
    width: float = (hi - lo) / bins
    for v in values:
        if v >= lo and v < hi:
            idx: int = int((v - lo) / width)
            if idx >= bins:
                idx = bins - 1
            counts[idx] += 1
    return counts

